#!/usr/bin/env bash
# Generates AnemoneSeerr's Seerr API client with swift-openapi-generator, from the spec and
# configuration in scripts/seerr-client/, into Packages/AnemoneKit/Sources/AnemoneSeerr/Generated.
#
# The generated sources are committed, so building the app or the package never runs the
# generator: a build plugin would need `-skipPackagePluginValidation`, which CI's
# `xcodebuild build` doesn't pass. Run this after changing the spec or the configuration (for
# example, to add an endpoint to the configuration's path filter), then commit the result.
#
# Each generated file is wrapped in `#if ANEMONE_SEERR`, like the rest of AnemoneSeerr, so builds
# without the flag leave the client out; see docs/seerr.md.
#
# The spec, seerr-api.yml, is Wholphin's copy of Seerr's API description (MIT); NOTICE.md
# credits both.
#
# usage: scripts/generate-seerr-client.sh

set -euo pipefail

repo="$(cd "$(dirname "$0")/.." && pwd)"
generator="$repo/scripts/seerr-client"
output="$repo/Packages/AnemoneKit/Sources/AnemoneSeerr/Generated"

if [[ $# -gt 0 ]]; then
    sed -n '2,17p' "$0" | sed 's/^# \{0,1\}//'
    exit 64
fi

scratch="$(mktemp -d)"
trap 'rm -rf "$scratch"' EXIT

swift run --package-path "$generator" swift-openapi-generator generate \
    --config "$generator/openapi-generator-config.yaml" \
    --output-directory "$scratch" \
    "$generator/seerr-api.yml"

mkdir -p "$output"
# SwiftLint is switched off for the generated code and on again at its end, except for
# file_length, which it checks at the very end and which only the long files would break.
for file in "$scratch"/*.swift; do
    name="$(basename "$file")"
    {
        echo "// Generated by scripts/generate-seerr-client.sh with swift-openapi-generator. Don't edit."
        echo "// swiftformat:disable all"
        echo "// swiftlint:disable all"
        echo "#if ANEMONE_SEERR"
        cat "$file"
        echo "// swiftlint:enable all"
        if (($(wc -l <"$file") > 390)); then
            echo "// swiftlint:disable file_length"
        fi
        echo "#endif"
    } >"$output/$name"
    echo "wrote $output/$name"
done
